values ('function_plot', 'Function plots', 'A typed function drawn over a domain with one feature marked: concavity, a zero, an inflection point, a hole, a tangency, a transformation, an asymptote, a sequence''s discrete points, or the same function at two scales. Functions carry numeric parameters rather than expression strings, polynomials go through Horner and exponentials through exp, so the two renderers agree byte for byte. A curve BREAKS where its function is undefined or leaves the window, because a line drawn through an asymptote asserts a value the function does not take.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-concavity', 'ap_precalculus', 'function_plot', 'Concave up and concave down', 'Which way it bends', 'Concave up where the rate of change is increasing, down where it is decreasing', 'One cubic. To the left of the origin the curve bends downwards — its slope is falling — and to the right it bends upwards, where the slope is rising. Concavity is about how the SLOPE changes, not whether the curve goes up or down.', 'The graph of a cubic function over the interval from minus three to three. To the left of zero the curve is concave down: it bends downwards, and although it is rising its slope is getting smaller. To the right of zero it is concave up: it bends upwards and its slope is getting larger. The two halves are labelled. Concavity describes how the RATE OF CHANGE is changing, not whether the function itself is increasing or decreasing, which is why a curve can be rising and concave down at the same time.', 'x', 'y', 'A curve can rise while bending downwards: concavity is about the slope, not the value.', true, null, '["Concave down where the rate of change is decreasing", "Concave up where the rate of change is increasing"]'::jsonb, '{"x_range": [-2.0, 2.0], "y_range": [-7.5, 7.5], "curves": [{"kind": "polynomial", "coeffs": [0.0, -1.0, 0.0, 1.0]}], "x_ticks": [[-1.0, "−1"], [0.0, "0"], [1.0, "1"]], "y_ticks": [-6, -3, 0, 3, 6], "texts": [{"x": -1.25, "y": 4.6, "label": "concave down"}, {"x": 1.25, "y": -4.6, "label": "concave up"}], "concavity_check": {"down": [-1.8, -0.3], "up": [0.3, 1.8]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-zero-of-a-function', 'ap_precalculus', 'function_plot', 'A zero of a function', 'Where it crosses', 'An input whose output is zero: where the graph meets the x-axis', 'The graph crosses the x-axis at x = −1 and x = 2. Each of those inputs is a zero: the output there is exactly 0, which is what the crossing shows.', 'The graph of a quadratic that crosses the horizontal axis twice, at x equals minus one and x equals two, with both crossings marked. A zero of a function is an input whose output is zero, so on a graph it is exactly where the curve meets the x-axis. Between the two zeros the curve dips below the axis, so the output is negative there; outside them it is positive. A zero is an INPUT value, not a point: the points here are (minus one, zero) and (two, zero).', 'x', 'y', 'A zero is the input, not the point: here they are x = −1 and x = 2.', true, null, '["Output is zero there", "The graph meets the x-axis"]'::jsonb, '{"x_range": [-2.5, 3.5], "y_range": [-3.5, 8.0], "curves": [{"kind": "polynomial", "coeffs": [-2.0, -1.0, 1.0]}], "x_ticks": [[-1.0, "−1"], [0.0, "0"], [2.0, "2"]], "y_ticks": [-2, 0, 2, 4, 6], "asymptotes_y": [{"y": 0.0, "label": "y = 0"}], "marks": [{"x": -1.0, "label": "zero at x = −1", "place": "above"}, {"x": 2.0, "label": "zero at x = 2", "place": "above"}], "zeros_check": [-1.0, 2.0]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-aroc-concavity', 'ap_precalculus', 'function_plot', 'Concavity read from average rates of change', 'Secants get steeper', 'Equal-width intervals, and the average rate of change rises across them', 'Three secants over equal-width intervals of one unit. Their slopes are 1, 3 and 5: the average rate of change increases from interval to interval, which is what makes this graph concave up.', 'A parabola with three dashed secant lines drawn over three touching intervals of equal width, from zero to one, one to two, and two to three. The secants get steeper from left to right: their slopes are one, three and five. Because the average rate of change over equal-width intervals is increasing, the graph is concave up. This is the definition of concavity that does not need calculus: compare average rates over equal intervals rather than looking at the bend by eye.', 'x', 'y', 'Slopes 1, 3, 5 over equal intervals: increasing, so concave up.', true, null, '["Equal-width intervals", "Average rate of change is increasing", "So the graph is concave up"]'::jsonb, '{"x_range": [-0.25, 3.4], "y_range": [-1.0, 13.0], "curves": [{"kind": "polynomial", "coeffs": [0.0, 0.0, 1.0]}], "x_ticks": [[0.0, "0"], [1.0, "1"], [2.0, "2"], [3.0, "3"]], "y_ticks": [0, 3, 6, 9, 12], "secants": [{"from": 0.0, "to": 1.0}, {"from": 1.0, "to": 2.0}, {"from": 2.0, "to": 3.0}], "texts": [{"x": 0.5, "y": 2.3, "label": "slope 1"}, {"x": 1.5, "y": 5.1, "label": "slope 3"}, {"x": 2.5, "y": 9.2, "label": "slope 5"}], "secant_slopes_check": [1.0, 3.0, 5.0], "points": [{"x": 0.0, "y": 0.0}, {"x": 1.0, "y": 1.0}, {"x": 2.0, "y": 4.0}, {"x": 3.0, "y": 9.0}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-inflection-point', 'ap_precalculus', 'function_plot', 'A point of inflection', 'Where the bend flips', 'The input where the graph changes concavity', 'The same cubic, with the point of inflection at the origin marked. To its left the graph is concave down; to its right, concave up. The inflection point is where the rate of change stops decreasing and starts increasing.', 'The graph of a cubic with a single marked point at the origin, labelled as the point of inflection. To the left of that point the curve is concave down and to the right it is concave up, so the marked point is where the concavity changes. It is not a maximum or a minimum: the function is increasing on both sides of it. What switches there is the direction of the bend, which is the same as saying the rate of change stops decreasing and starts increasing.', 'x', 'y', 'Not a maximum or minimum: the function is increasing on both sides.', true, null, '["Concavity changes there", "The rate of change switches between decreasing and increasing"]'::jsonb, '{"x_range": [-2.0, 2.0], "y_range": [-8.0, 8.0], "curves": [{"kind": "polynomial", "coeffs": [0.0, 1.0, 0.0, 0.6]}], "x_ticks": [[-1.0, "−1"], [0.0, "0"], [1.0, "1"]], "y_ticks": [-6, -3, 0, 3, 6], "marks": [{"x": 0.0, "label": "point of inflection", "place": "above"}], "concavity_check": {"down": [-1.8, -0.3], "up": [0.3, 1.8]}, "inflection_check": 0.0}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-even-multiplicity-zero', 'ap_precalculus', 'function_plot', 'A zero of even multiplicity', 'Touch, don''t cross', 'The graph is tangent to the axis there, and the sign does not change', 'f(x) = (x + 2)(x − 1)². At x = −2 the zero is simple and the graph crosses the axis. At x = 1 the zero is doubled: the graph touches the axis and turns back, so the output keeps the same sign either side.', 'The graph of a cubic with two zeros. At x equals minus two the curve passes straight through the horizontal axis, going from negative to positive, because that zero has multiplicity one. At x equals one the curve comes down to the axis, touches it, and turns back upwards without crossing: that zero has multiplicity two. Either side of x equals one the output is positive, so the sign does not change there, and the curve is tangent to the axis at that point rather than cutting it. Even multiplicity means touch; odd multiplicity means cross.', 'x', 'y', 'Even multiplicity: touch and turn back. Odd multiplicity: cross.', true, null, '["Tangent to the x-axis at the even-multiplicity zero", "Output signs are the same either side of it", "An odd-multiplicity zero crosses instead"]'::jsonb, '{"x_range": [-2.6, 2.0], "y_range": [-9.0, 6.0], "curves": [{"kind": "polynomial", "coeffs": [2.0, -3.0, 0.0, 1.0]}], "x_ticks": [[-2.0, "−2"], [0.0, "0"], [1.0, "1"]], "y_ticks": [-6, -3, 0, 3], "asymptotes_y": [{"y": 0.0, "label": "y = 0"}], "marks": [{"x": 1.0, "label": "tangent here", "place": "below"}], "tangency_check": {"x": 1.0, "crosses": -2.0}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-hole', 'ap_precalculus', 'function_plot', 'A hole in a rational function', 'Hole at (2, 4)', 'The limit exists from both sides, but the function is not defined there', 'r(x) = (x² − 4)/(x − 2) simplifies to x + 2 everywhere except x = 2, where it is undefined. Inputs close to 2 give outputs close to 4, so the hole is at (2, 4), drawn as an open circle.', 'A straight line rising from lower left to upper right, with a single open circle at the point two comma four. The function is a rational expression whose numerator and denominator share a factor, so it equals x plus two everywhere except at x equals two, where it is undefined. Inputs just below and just above two both give outputs arbitrarily close to four, so the limit from each side is four and the hole sits at the point two comma four. The circle is drawn open, not filled, because the function does not take that value: a filled dot would say the opposite.', 'x', 'y', 'Open circle: the limit is 4, but r(2) does not exist.', true, null, '["The limit from both sides", "The hole sits at that point", "The function is undefined there"]'::jsonb, '{"x_range": [-1.0, 5.0], "y_range": [0.0, 8.0], "curves": [{"kind": "polynomial", "coeffs": [2.0, 1.0]}], "x_ticks": [[0.0, "0"], [2.0, "2"], [4.0, "4"]], "y_ticks": [0, 2, 4, 6], "open_points": [{"x": 2.0, "y": 4.0}], "texts": [{"x": 2.0, "y": 5.0, "label": "hole at (2, 4)"}], "hole_check": {"x": 2.0, "y": 4.0}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-transformations-additive', 'ap_precalculus', 'function_plot', 'Additive transformations translate the graph', 'Translations', 'f(x) + k moves it vertically; f(x + h) moves it horizontally by −h', 'The parent f(x) = 0.5x² with two additive transformations. Adding 3 to the OUTPUT lifts the graph three units. Adding −2 to the INPUT moves it two units to the right — the opposite direction to the sign, which is the part students misread.', 'Three parabolas. The solid one is the parent function, one half x squared, with its vertex at the origin. One dashed curve is the same shape lifted three units, which is the parent with three added to its output. The other dashed curve is the same shape moved two units to the RIGHT, which is the parent with minus two added to its input. A change to the output moves the graph the way the sign reads; a change to the input moves it the opposite way, so adding a negative number inside shifts right rather than left.', 'x', 'y', 'Inside the function, the shift goes the OPPOSITE way to the sign.', true, null, '["g(x) = f(x) + k", "g(x) = f(x + h)"]'::jsonb, '{"x_range": [-2.6, 4.2], "y_range": [-1.0, 12.5], "curves": [{"kind": "polynomial", "coeffs": [0.0, 0.0, 0.5], "label": "f(x)", "style": "solid"}, {"kind": "polynomial", "coeffs": [3.0, 0.0, 0.5], "label": "f(x) + 3", "style": "dashed"}, {"kind": "polynomial", "coeffs": [2.0, -2.0, 0.5], "label": "f(x − 2)", "style": "dashed"}], "x_ticks": [[-2.0, "−2"], [0.0, "0"], [2.0, "2"], [4.0, "4"]], "y_ticks": [0, 3, 6, 9, 12]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-transformations-multiplicative', 'ap_precalculus', 'function_plot', 'Multiplicative transformations stretch and reflect', 'Dilations', 'a f(x) scales vertically; f(bx) scales horizontally by 1/b', 'The same parent with two multiplicative transformations. Multiplying the OUTPUT by −1 reflects the graph over the x-axis. Multiplying the INPUT by 2 compresses it horizontally by a factor of one half — again the reciprocal, not the factor itself.', 'Three curves sharing a vertex at the origin. The solid one is the parent, one half x squared. One dashed curve is its mirror image below the horizontal axis, which is the parent multiplied by minus one: a vertical dilation with a reflection. The other dashed curve is much narrower than the parent, which is the parent with its input multiplied by two: a horizontal dilation by a factor of one half. A factor applied to the output scales the graph by that factor; a factor applied to the input scales it by the RECIPROCAL, so multiplying the input by two makes the graph half as wide, not twice as wide.', 'x', 'y', 'Inside the function, the factor acts as its RECIPROCAL.', true, null, '["g(x) = a f(x), a ≠ 0", "g(x) = f(bx), b ≠ 0"]'::jsonb, '{"x_range": [-2.6, 2.6], "y_range": [-4.5, 14.0], "curves": [{"kind": "polynomial", "coeffs": [0.0, 0.0, 0.5], "label": "f(x)", "style": "solid"}, {"kind": "polynomial", "coeffs": [0.0, 0.0, -0.5], "label": "−f(x)", "style": "dashed"}, {"kind": "polynomial", "coeffs": [0.0, 0.0, 2.0], "label": "f(2x)", "style": "dashed"}], "x_ticks": [[-2.0, "−2"], [0.0, "0"], [2.0, "2"]], "y_ticks": [-4, 0, 4, 8, 12]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-degree-from-points', 'ap_precalculus', 'function_plot', 'How many points fix a polynomial''s degree', 'n + 1 points', 'Four points with distinct inputs are modelled by a cubic — degree 3 or less', 'Four points with distinct x values, and the cubic through them. In general n + 1 points with distinct inputs are modelled by a polynomial of degree n or less: four points give degree 3 or less, not necessarily exactly 3.', 'Four marked points with distinct horizontal positions, at x equals minus one, zero, one and two, with a single smooth cubic curve passing through all four. Four points with distinct inputs determine a polynomial of degree three or less. Degree three OR LESS matters: if the four points happened to lie on a straight line, the polynomial through them would be degree one, and the count of points sets an upper bound on the degree rather than fixing it exactly.', 'x', 'y', 'n + 1 points give degree n or LESS — an upper bound, not an exact degree.', true, null, '["Four points with distinct inputs", "A polynomial of degree 3 or less fits them"]'::jsonb, '{"x_range": [-1.6, 2.4], "y_range": [-1.6, 12.0], "curves": [{"kind": "polynomial", "coeffs": [1.0, -2.0, 0.0, 1.0]}], "x_ticks": [[-1.0, "−1"], [0.0, "0"], [1.0, "1"], [2.0, "2"]], "y_ticks": [0, 3, 6, 9], "points": [{"x": -1.0, "y": 2.0}, {"x": 0.0, "y": 1.0}, {"x": 1.0, "y": 0.0}, {"x": 2.0, "y": 5.0}], "degree_points_check": {"degree": 3, "xs": [-1.0, 0.0, 1.0, 2.0]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-sequence', 'ap_precalculus', 'function_plot', 'A sequence is a function on the whole numbers', 'Discrete points', 'Its graph is a set of points, not a curve', 'The sequence aₙ = 2n + 1 for n = 0 to 6. The graph is seven separate points. There is nothing between them to draw: the sequence has no value at n = 1.5.', 'Seven separate dots rising steadily from left to right, at horizontal positions zero through six and heights one, three, five, seven, nine, eleven and thirteen. This is the graph of a sequence, which is a function whose inputs are the whole numbers. The dots are not joined, because the sequence has no value between consecutive whole numbers: there is no term at n equals one and a half. Drawing a line through them would assert values the sequence does not have, which is the difference between a sequence and a function on the real numbers. The graph is therefore discrete.', 'n', 'aₙ', 'Not joined: there is no term between consecutive whole numbers.', true, null, '["Inputs are the whole numbers", "The graph is a set of discrete points"]'::jsonb, '{"x_range": [-0.6, 6.6], "y_range": [0.0, 15.0], "curves": [], "x_ticks": [[0.0, "0"], [2.0, "2"], [4.0, "4"], [6.0, "6"]], "y_ticks": [0, 3, 6, 9, 12, 15], "points": [{"x": 0.0, "y": 1.0}, {"x": 1.0, "y": 3.0}, {"x": 2.0, "y": 5.0}, {"x": 3.0, "y": 7.0}, {"x": 4.0, "y": 9.0}, {"x": 5.0, "y": 11.0}, {"x": 6.0, "y": 13.0}], "sequence_check": true}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-exponential-shape', 'ap_precalculus', 'function_plot', 'The shape of an exponential function', 'No turns, no flex', 'Always increasing or always decreasing, always one way concave, and no extremum', 'f(x) = 2ˣ. It rises everywhere, bends upwards everywhere, and never turns: an exponential has no maximum, no minimum and no point of inflection, and its graph approaches the x-axis without reaching it.', 'The graph of two to the power x, rising from near zero on the left to eight on the right. It increases at every point and is concave up at every point, so it never turns around and never changes the direction of its bend. That is why an exponential function has no maximum, no minimum and no point of inflection, except that a maximum and minimum do exist if you restrict it to a closed interval, where they occur at the endpoints. The dashed line at y equals zero is a horizontal asymptote: the curve approaches it without ever reaching it.', 'x', 'y', 'Extrema only on a closed interval, and then only at its endpoints.', true, null, '["Always increasing", "Always concave up", "No extremum and no point of inflection"]'::jsonb, '{"x_range": [-2.2, 3.0], "y_range": [-0.8, 9.0], "curves": [{"kind": "exponential", "a": 1.0, "r": 0.6931471805599453}], "x_ticks": [[-2.0, "−2"], [0.0, "0"], [2.0, "2"]], "y_ticks": [0, 2, 4, 6, 8], "asymptotes_y": [{"y": 0.0, "label": "y = 0"}], "monotone_check": "increasing"}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-log-reflection', 'ap_precalculus', 'function_plot', 'A logarithm is its exponential reflected over y = x', 'Mirror in y = x', 'If (s, t) lies on bˣ then (t, s) lies on logᵇ x', 'f(x) = 2ˣ and g(x) = log₂ x, with the line y = x between them. Each curve is the other''s mirror image in that line, so every ordered pair on one appears with its coordinates swapped on the other: (1, 2) on the exponential becomes (2, 1) on the logarithm.', 'Two curves and a straight diagonal line. The steeply rising curve is two to the power x; the slowly rising one is the logarithm base two of x; the diagonal is the line y equals x. The two curves are mirror images of each other in that diagonal. Reflecting a point over y equals x swaps its coordinates, so a point at one comma two on the exponential corresponds to a point at two comma one on the logarithm. That is what makes the two functions inverses: the exponential''s outputs are the logarithm''s inputs and the other way round. The logarithm is drawn only for positive inputs, because that is its whole domain.', 'x', 'y', 'Reflecting over y = x swaps the coordinates: (s, t) becomes (t, s).', true, null, '["Each is the other''s reflection over y = x", "Swapping an ordered pair''s coordinates", "The logarithm is defined only for positive inputs"]'::jsonb, '{"x_range": [-1.0, 5.0], "y_range": [-1.0, 5.0], "curves": [{"kind": "exponential", "a": 1.0, "r": 0.6931471805599453, "y_clip": 5.0, "label": "2ˣ", "style": "solid"}, {"kind": "logarithm", "a": 1.0, "ln_base": 0.6931471805599453, "label": "log₂ x", "style": "solid", "y_clip": 5.0}, {"kind": "identity", "label": "y = x", "style": "dashed"}], "x_ticks": [[0.0, "0"], [1.0, "1"], [2.0, "2"], [4.0, "4"]], "y_ticks": [0, 1, 2, 4], "points": [{"x": 1.0, "y": 2.0}, {"x": 2.0, "y": 1.0}], "reflection_check": {"a": 0, "b": 1, "sample_x": [0.0, 1.0, 2.0]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-sinusoid-concavity', 'ap_precalculus', 'function_plot', 'A sinusoid alternates concavity', 'Bend flips each half', 'Concave down over each crest, concave up over each trough', 'y = sin x over two full periods. Between 0 and π the graph is concave down; between π and 2π it is concave up; and the pattern repeats. The bend flips at every point where the curve crosses its midline.', 'The sine curve drawn over two full periods, from zero to four pi. Over the first hump, between zero and pi, the graph is concave down: it bends downwards throughout, even while it is rising on the way up to the crest. Between pi and two pi it is concave up, bending upwards throughout. The pattern then repeats. The concavity changes exactly where the curve crosses its midline, at zero, pi, two pi, three pi and four pi, and those crossings are the points of inflection. Rising and falling is not the same as concave up and down: the curve is rising and concave down on the first quarter period.', 'x', 'y', 'The bend flips at each midline crossing — those are the inflection points.', true, null, '["Concave down over a crest", "Concave up over a trough", "Alternating as x increases"]'::jsonb, '{"x_range": [0.0, 12.566370614359172], "y_range": [-1.45, 1.45], "curves": [{"kind": "sine", "a": 1.0, "b": 1.0}], "x_ticks": [[0.0, "0"], [3.141592653589793, "π"], [6.283185307179586, "2π"], [9.42477796076938, "3π"], [12.566370614359172, "4π"]], "y_ticks": [-1, 0, 1], "texts": [{"x": 1.5707963267948966, "y": 1.28, "label": "concave down"}, {"x": 4.71238898038469, "y": -1.28, "label": "concave up"}], "concavity_check": {"down": [0.35, 2.78], "up": [3.5, 5.93]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-tangent-reflections', 'ap_precalculus', 'function_plot', 'A negative coefficient reflects the tangent graph', 'a < 0 flips it', 'a tan θ with a < 0 is the graph reflected over the x-axis', 'y = tan θ and y = −tan θ on one pair of axes. The negative outside coefficient reflects the graph over the x-axis. A negative coefficient INSIDE, tan(bθ) with b < 0, reflects over the y-axis instead — which for tangent gives the same curve, because tangent is an odd function.', 'Two sets of tangent branches between vertical dashed asymptotes. The solid branches rise from bottom left to top right between consecutive asymptotes; the dashed branches are their mirror image in the horizontal axis, falling instead of rising. That mirror image is y equals minus tangent theta: a negative coefficient outside the function reflects the graph over the x-axis. A negative coefficient inside, as in tangent of b theta with b negative, reflects over the y-axis instead; for tangent those two reflections happen to produce the same curve, because tangent is an odd function, so minus tangent theta and tangent of minus theta are equal. The curves are broken at each asymptote rather than drawn through it, because the function has no value there.', 'θ', 'y', 'For tangent the two reflections coincide: tan(−θ) = −tan θ.', true, null, '["a < 0 reflects the graph over the x-axis", "b < 0 reflects it over the y-axis", "Vertical asymptotes where cosine is zero"]'::jsonb, '{"x_range": [-4.71238898038469, 4.71238898038469], "y_range": [-4.0, 4.0], "curves": [{"kind": "tangent", "a": 1.0, "b": 1.0, "cut": 4.0, "label": "tan θ", "style": "solid"}, {"kind": "tangent", "a": -1.0, "b": 1.0, "cut": 4.0, "label": "−tan θ", "style": "dashed"}], "x_ticks": [[-3.141592653589793, "−π"], [0.0, "0"], [3.141592653589793, "π"]], "y_ticks": [-3, 0, 3], "asymptotes_x": [-4.71238897938469, -1.5707963267948966, 1.5707963267948966, 4.71238897938469], "asymptote_check": {"eps": 0.02, "big": 20.0}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-secant-graph', 'ap_precalculus', 'function_plot', 'The secant graph', 'sec: gaps at ±1', 'Vertical asymptotes where cosine is zero, and no values between −1 and 1', 'y = sec θ. It has a vertical asymptote wherever cos θ = 0, and its range is everything at or beyond 1 in each direction: no point of the graph lies strictly between −1 and 1.', 'The secant graph, drawn as separate U-shaped branches between vertical dashed asymptotes. Each asymptote sits where the cosine is zero, because secant is one over cosine and dividing by zero has no value. Every branch opens away from the horizontal axis, and no part of the graph lies strictly between minus one and one: the range is everything at or below minus one together with everything at or above one. The branches are broken at the asymptotes rather than joined across them.', 'θ', 'y', 'Range: (−∞, −1] ∪ [1, ∞). Nothing strictly between.', true, null, '["Secant"]'::jsonb, '{"x_range": [-4.71238898038469, 4.71238898038469], "y_range": [-6.0, 6.0], "curves": [{"kind": "secant", "a": 1.0, "b": 1.0, "cut": 6.0}], "x_ticks": [[-3.141592653589793, "−π"], [0.0, "0"], [3.141592653589793, "π"]], "y_ticks": [-4, -1, 0, 1, 4], "asymptotes_x": [-1.5707963267948966, 1.5707963267948966], "asymptote_check": {"eps": 0.02, "big": 20.0}, "range_gap_check": [-1.0, 1.0]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-cosecant-graph', 'ap_precalculus', 'function_plot', 'The cosecant graph', 'csc: gaps at ±1', 'Vertical asymptotes where sine is zero, and the same excluded band', 'y = csc θ. Its asymptotes sit where sin θ = 0 — at 0 and at every multiple of π — and like the secant it takes no value strictly between −1 and 1.', 'The cosecant graph, drawn as separate U-shaped branches between vertical dashed asymptotes. The asymptotes sit where the sine is zero, which is at zero and at every multiple of pi, because cosecant is one over sine. As with the secant, no part of the graph lies strictly between minus one and one. The difference between the two is only where the asymptotes fall: the secant''s are where cosine vanishes, the cosecant''s where sine does, which is a quarter period apart.', 'θ', 'y', 'Same excluded band as the secant; the asymptotes sit a quarter period away.', true, null, '["Cosecant"]'::jsonb, '{"x_range": [-4.71238898038469, 4.71238898038469], "y_range": [-6.0, 6.0], "curves": [{"kind": "cosecant", "a": 1.0, "b": 1.0, "cut": 6.0}], "x_ticks": [[-3.141592653589793, "−π"], [0.0, "0"], [3.141592653589793, "π"]], "y_ticks": [-4, -1, 0, 1, 4], "asymptotes_x": [-3.141592653589793, 0.0, 3.141592653589793], "asymptote_check": {"eps": 0.02, "big": 20.0}, "range_gap_check": [-1.0, 1.0]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('precalc-cotangent-graph', 'ap_precalculus', 'function_plot', 'The cotangent graph', 'cot: always falling', 'Asymptotes where tangent is zero, and decreasing between consecutive ones', 'y = cot θ. Its asymptotes sit where tan θ = 0, and between any two consecutive asymptotes the graph falls the whole way — unlike the secant and cosecant, it takes every real value.', 'The cotangent graph, drawn as separate branches between vertical dashed asymptotes. Each branch starts high on the left of its interval and falls steadily to low on the right, so the function is decreasing between consecutive asymptotes rather than turning. The asymptotes sit where the tangent is zero, which is at zero and at every multiple of pi. Unlike the secant and the cosecant there is no excluded band: a cotangent branch passes through every real value between its two asymptotes.', 'θ', 'y', 'Decreasing between consecutive asymptotes, and no excluded range.', true, null, '["Cotangent"]'::jsonb, '{"x_range": [-4.71238898038469, 4.71238898038469], "y_range": [-6.0, 6.0], "curves": [{"kind": "cotangent", "a": 1.0, "b": 1.0, "cut": 6.0}], "x_ticks": [[-3.141592653589793, "−π"], [0.0, "0"], [3.141592653589793, "π"]], "y_ticks": [-4, 0, 4], "asymptotes_x": [-3.141592653589793, 0.0, 3.141592653589793], "asymptote_check": {"eps": 0.02, "big": 20.0}, "decreasing_between_check": {"intervals": [[-2.891592653589793, -0.25], [0.25, 2.891592653589793]]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('calcab-scale-hides-behaviour-wide', 'ap_calculus_ab', 'function_plot', 'The same function, seen at the usual scale', 'Looks monotonic', 'At this window f(x) = x³ − 0.01x looks like it only ever rises', 'f(x) = x³ − 0.01x over −2 ≤ x ≤ 2. At this scale the graph appears to rise steadily through the origin with no turning points at all. Nothing here suggests otherwise.', 'The graph of x cubed minus one hundredth of x, drawn over the interval from minus two to two with the vertical axis running from about minus eight to eight. At this scale it looks exactly like a plain cubic rising steadily through the origin, with no flat part and no turning points. The behaviour near the origin is far too small to see: the whole feature is about four ten-thousandths tall, which at this scale is less than the thickness of the drawn line. A limit or a shape read off this picture alone would be wrong, which is why a graph is evidence about a function rather than proof.', 'x', 'y', 'Nothing visible near the origin — at this scale the feature is thinner than the line.', true, null, '["At this scale the graph looks monotonic"]'::jsonb, '{"x_range": [-2.0, 2.0], "y_range": [-8.5, 8.5], "curves": [{"kind": "polynomial", "coeffs": [0.0, -0.01, 0.0, 1.0]}], "x_ticks": [[-2.0, "−2"], [0.0, "0"], [2.0, "2"]], "y_ticks": [-8, -4, 0, 4, 8], "window_pair_check": {"visible": false, "coeffs": [0.0, -0.01, 0.0, 1.0]}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('calcab-scale-hides-behaviour-zoom', 'ap_calculus_ab', 'function_plot', 'The same function, zoomed in near the origin', 'It turns twice', 'The window is a thousand times smaller, and two turning points appear', 'The identical function over −0.15 ≤ x ≤ 0.15, with the vertical axis a thousand times finer. There are two turning points, at about x = ±0.058, and a stretch where the function decreases — none of which the wide view showed.', 'The graph of the same function, x cubed minus one hundredth of x, over a window about thirteen times narrower horizontally and ten thousand times finer vertically. Now a local maximum and a local minimum are plainly visible, at about x equals minus zero point zero five eight and plus zero point zero five eight, with the function decreasing between them. This is the behaviour the wide view could not show. Both pictures are of the same function and both are accurate; only the scale differs, which is why a graph-based estimate of a limit or of a shape should be treated with care rather than trusted.', 'x', 'y', 'Same function, same accuracy — only the scale differs.', true, null, '["Zoomed in, the same graph turns twice"]'::jsonb, '{"x_range": [-0.15, 0.15], "y_range": [-0.00085, 0.00085], "curves": [{"kind": "polynomial", "coeffs": [0.0, -0.01, 0.0, 1.0]}], "x_ticks": [[-0.1, "−0.1"], [0.0, "0"], [0.1, "0.1"]], "y_ticks": [-0.0008, -0.0004, 0.0, 0.0004, 0.0008], "window_pair_check": {"visible": true, "coeffs": [0.0, -0.01, 0.0, 1.0]}}'::jsonb, '{:.4f}', null, 'published', 'cramapple-authored; batch=precalc-,calcab-figures-2026-10-11', now())
on conflict (figure_id) do nothing;

