-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('precalc-concavity', 'precalc-zero-of-a-function', 'precalc-aroc-concavity', 'precalc-inflection-point', 'precalc-even-multiplicity-zero', 'precalc-hole', 'precalc-transformations-additive', 'precalc-transformations-multiplicative', 'precalc-degree-from-points', 'precalc-sequence', 'precalc-exponential-shape', 'precalc-log-reflection', 'precalc-sinusoid-concavity', 'precalc-tangent-reflections', 'precalc-secant-graph', 'precalc-cosecant-graph', 'precalc-cotangent-graph', 'calcab-scale-hides-behaviour-wide', 'calcab-scale-hides-behaviour-zoom') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('precalc-concavity', 'precalc-zero-of-a-function', 'precalc-aroc-concavity', 'precalc-inflection-point', 'precalc-even-multiplicity-zero', 'precalc-hole', 'precalc-transformations-additive', 'precalc-transformations-multiplicative', 'precalc-degree-from-points', 'precalc-sequence', 'precalc-exponential-shape', 'precalc-log-reflection', 'precalc-sinusoid-concavity', 'precalc-tangent-reflections', 'precalc-secant-graph', 'precalc-cosecant-graph', 'precalc-cotangent-graph', 'calcab-scale-hides-behaviour-wide', 'calcab-scale-hides-behaviour-zoom');
  if v_n <> 19 then
    raise exception 'expected 19 figures, found %', v_n;
  end if;
end $$;

commit;
